package com.mirigangneung.infrastructure.storage;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@Component public class LocalTemporaryImageStorage implements TemporaryImageStorage { private final Path root; public LocalTemporaryImageStorage(@Value("${image.temp-dir}")String dir){root=Path.of(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException e){throw new IllegalStateException(e);}}
 public String save(InputStream in,String type,long size,Instant expires) throws IOException {String key=UUID.randomUUID()+extension(type);Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new IOException("invalid path");Files.copy(in,p,StandardCopyOption.REPLACE_EXISTING);return key;} public InputStream open(String key)throws IOException{return Files.newInputStream(safe(key));} public void delete(String key)throws IOException{Files.deleteIfExists(safe(key));} public boolean exists(String key){try{return Files.exists(safe(key));}catch(IOException e){return false;}} private Path safe(String k)throws IOException{Path p=root.resolve(k).normalize();if(!p.startsWith(root))throw new IOException("invalid path");return p;} private String extension(String t){return "image/png".equals(t)?".png":"image/jpeg".equals(t)?".jpg":".bin";}}
